import React from 'react';
import { Link, NavLink, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const isRecruiterLike = user && ['RECRUITER', 'HIRING_MANAGER', 'ADMIN'].includes(user.role);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const getInitials = (name) => {
    if (!name) return 'U';
    const parts = name.trim().split(' ');
    if (parts.length >= 2) return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
    return name.slice(0, 2).toUpperCase();
  };

  const isBuilderPage = location.pathname.startsWith('/resume/');

  return (
    <header className="site-navbar-wrapper">
      <nav className="site-navbar">
        <div className="nav-left">
          <Link to={user ? "/dashboard" : "/login"} className="brand-logo">
            <div className="brand-icon-box">
              <span className="brand-icon">⚡</span>
            </div>
            <span className="brand-text">
              Resume<span className="brand-gradient">Craft</span>
            </span>
          </Link>
        </div>

        <div className="nav-center">
          {user && (
            <div className="nav-links-pill">
              <NavLink
                to="/dashboard"
                className={({ isActive }) => `nav-item-link ${isActive ? 'active' : ''}`}
              >
                📊 Dashboard
              </NavLink>
              {!isRecruiterLike && (
                <NavLink
                  to="/templates"
                  className={({ isActive }) => `nav-item-link ${isActive ? 'active' : ''}`}
                >
                  🎨 Templates
                </NavLink>
              )}
              {isRecruiterLike && (
                <NavLink
                  to="/recruiter"
                  className={({ isActive }) => `nav-item-link ${isActive ? 'active' : ''}`}
                >
                  🔍 Search Candidates
                </NavLink>
              )}
            </div>
          )}
        </div>

        <div className="nav-right">
          {user ? (
            <div className="user-profile-menu">
              {!isRecruiterLike && !isBuilderPage && (
                <Link to="/resume/new" className="btn-nav-create">
                  <span>+</span> New Resume
                </Link>
              )}
              <div className="user-avatar-badge" title={`${user.fullName} (${user.role})`}>
                <div className="avatar-circle-sm">
                  {getInitials(user.fullName)}
                </div>
                <div className="user-meta-info">
                  <span className="user-name-text">{user.fullName.split(' ')[0]}</span>
                  <span className="user-role-pill">
                    {user.role === 'JOB_SEEKER' ? 'Job Seeker' : user.role.replace('_', ' ')}
                  </span>
                </div>
              </div>
              <button onClick={handleLogout} className="btn-nav-logout" title="Sign out">
                🚪 Logout
              </button>
            </div>
          ) : (
            <div className="auth-nav-buttons">
              <NavLink to="/login" className="btn-nav-ghost">Sign In</NavLink>
              <NavLink to="/register" className="btn-nav-solid">Get Started Free</NavLink>
            </div>
          )}
        </div>
      </nav>
    </header>
  );
}
